<?php
namespace ControleOnline\Service;
use ControleOnline\Entity\{DeliveryCourierVehicle,InvoiceTax,Mdfe,People};
use Doctrine\ORM\EntityManagerInterface;
use Symfony\Component\HttpKernel\Exception\BadRequestHttpException;
use Symfony\Component\Security\Core\Authentication\Token\Storage\TokenStorageInterface;
final class EmitMdfeService { public function __construct(private EntityManagerInterface $manager,private IntegrationService $integrations,private TokenStorageInterface $tokens){} public function create(array $raw,int $vehicleId,int $driverId,?int $insurerId):Mdfe{$ids=array_values(array_unique(array_filter(array_map('intval',$raw))));if(!$ids)throw new BadRequestHttpException('Selecione ao menos uma NF para o MDF-e.');if($vehicleId<1||$driverId<1)throw new BadRequestHttpException('Veículo e motorista são obrigatórios.');$docs=$this->manager->getRepository(InvoiceTax::class)->findBy(['id'=>$ids]);$v=$this->manager->getRepository(DeliveryCourierVehicle::class)->find($vehicleId);$d=$this->manager->getRepository(People::class)->find($driverId);$i=$insurerId?$this->manager->getRepository(People::class)->find($insurerId):null;if(count($docs)!==count($ids)||!$v||!$d||($insurerId&&!$i))throw new BadRequestHttpException('Veículo, pessoas ou NFs não encontrados.');$companies=[];foreach($docs as $doc){$c=$doc->getCompany()?:$doc->getIssuer();if($c instanceof People)$companies[$c->getId()]=$c;}if(count($companies)!==1)throw new BadRequestHttpException('As NFs devem pertencer à mesma empresa.');$m=(new Mdfe())->setCompany(reset($companies))->setVehicle($v)->setDriver($d)->setInsurer($i)->setStatus('pending');foreach($docs as $doc)$m->addDocument($doc);$this->manager->persist($m);$this->manager->flush();$u=$this->tokens->getToken()?->getUser();$this->integrations->addIntegration(json_encode(['mdfeId'=>$m->getId(),'invoiceTaxIds'=>$ids]),'MdfeEmission',null,is_object($u)?$u:null);return $m;}}
